import{_ as r,a as o,b as a,c as t,d as n,e as i,f as s,g as l,h as c}from"./chunks/x25_evo_quickstart_09.o4yPF9sk.js";import{_ as d,o as h,c as p,al as u}from"./chunks/framework.7vp1BMOE.js";const P=JSON.parse('{"title":"CUAV X25 EVO Wiring Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/assembly/quick_start_cuav_x25_evo.md","filePath":"en/assembly/quick_start_cuav_x25_evo.md"}'),m={name:"en/assembly/quick_start_cuav_x25_evo.md"};function f(g,e,y,v,b,_){return h(),p("div",null,[...e[0]||(e[0]=[u('<h1 id="cuav-x25-evo-wiring-quick-start" tabindex="-1">CUAV X25 EVO Wiring Quick Start <a class="header-anchor" href="#cuav-x25-evo-wiring-quick-start" aria-label="Permalink to &quot;CUAV X25 EVO Wiring Quick Start&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>This quick start guide shows how to power the <a href="./../flight_controller/cuav_x25-evo">X25 EVO</a> flight controller and connect its most important peripherals.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The following flight controller models are applicable to this quick start guide. <a href="./../flight_controller/cuav_x25-super">CUAV X25 SUPER</a><a href="./../flight_controller/cuav_x25-mega">CUAV X25 MEGA</a></p></div><h2 id="wiring-chart-overview" tabindex="-1">Wiring Chart Overview <a class="header-anchor" href="#wiring-chart-overview" aria-label="Permalink to &quot;Wiring Chart Overview&quot;">​</a></h2><p>The image below shows how to connect the most important sensors and peripherals (except the motor and servo outputs). We&#39;ll go through each of these in detail in the following sections.</p><p><img src="'+r+'" alt="wiring"></p><table tabindex="0"><thead><tr><th style="text-align:left;">Interface</th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:left;">POWER C1/C2</td><td style="text-align:left;">Connect the PMU2 Lite to this port; this port is used for connecting the DroneCAN power module</td></tr><tr><td style="text-align:left;">M1 ~ M16</td><td style="text-align:left;">PWM signal output ports, usable for controlling motors or servos; support 3.3V/5V PWM configuration</td></tr><tr><td style="text-align:left;">RC IN</td><td style="text-align:left;">Connect remote controller receivers with one-way protocols (e.g., SBUS/DSM/PPM). Note: ELRS/CRSF receivers should be connected to any serial port, not RC IN</td></tr><tr><td style="text-align:left;">RSSI</td><td style="text-align:left;">For connecting signal strength feedback modules</td></tr><tr><td style="text-align:left;">GPS&amp;SAFETY</td><td style="text-align:left;">Connect Neo-series GPS or C-RTK-series RTK; this port includes interfaces for GPS, safety switch, and buzzer</td></tr><tr><td style="text-align:left;">GPS2</td><td style="text-align:left;">Usable for connecting additional GPS/RTK modules</td></tr><tr><td style="text-align:left;">DEBUG (DSU)</td><td style="text-align:left;">For FMU chip debugging and reading debug device information; with ArduPilot firmware, it can be configured for other serial port functions</td></tr><tr><td style="text-align:left;">ADC3V3</td><td style="text-align:left;">For analog level signal detection; the maximum detectable level signal is 3.3V</td></tr><tr><td style="text-align:left;">ADC6V6</td><td style="text-align:left;">For analog level signal detection; the maximum detectable level signal is 6.6V (PX4 is not supported.)</td></tr><tr><td style="text-align:left;">TF CARD</td><td style="text-align:left;">Insert an SD card here to enable log storage functionality</td></tr><tr><td style="text-align:left;">ETH</td><td style="text-align:left;">Ethernet port, usable for connecting Ethernet devices such as companion computers</td></tr><tr><td style="text-align:left;">I2C1/2/3</td><td style="text-align:left;">Connect external I2C devices (e.g., external compasses) for communication between the controller and I2C devices</td></tr><tr><td style="text-align:left;">TELEM1/TELEM2</td><td style="text-align:left;">Connect telemetry modules (for data transmission) to enable MAVLINK data interaction</td></tr><tr><td style="text-align:left;">CAN1/2</td><td style="text-align:left;">For communication between the controller and DroneCAN devices (e.g., connecting NEO4 SE GPS)</td></tr><tr><td style="text-align:left;">TYPE C</td><td style="text-align:left;">USB port of the controller, usable for connecting to the ground station, flashing firmware, and other operations</td></tr><tr><td style="text-align:left;">SPI6</td><td style="text-align:left;">SPI port for external expansion; generally not used</td></tr></tbody></table><h2 id="vehicle-front" tabindex="-1">Vehicle Front <a class="header-anchor" href="#vehicle-front" aria-label="Permalink to &quot;Vehicle Front&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If the controller cannot be mounted in the recommended/default orientation (e.g. due to space constraints) you will need to configure the autopilot software with the orientation that you actually used: <a href="./../config/flight_controller_orientation">Flight Controller Orientation</a>.</p></div><p><img src="'+o+'" alt="front"></p><h2 id="gps-compass-buzzer-safety-switch-led" tabindex="-1">GPS + Compass + Buzzer + Safety Switch + LED <a class="header-anchor" href="#gps-compass-buzzer-safety-switch-led" aria-label="Permalink to &quot;GPS + Compass + Buzzer + Safety Switch + LED&quot;">​</a></h2><p>We recommend using a CAN GPS/RTK (such as <a href="https://store.cuav.net/shop/cuav-neo-4-se-gps-module/" target="_blank" rel="noreferrer">Neo 4SE</a>); simply connect it to the <strong>CAN 1</strong> or <strong>CAN 2</strong> port.</p><p>You can also use a standard GPS/RTK module(such as <a href="https://store.cuav.net/shop/neo-3-pro/" target="_blank" rel="noreferrer">NEO3 GPS</a> (10-pin connector)) by connecting it to the <strong>GPS&amp;SAFETY</strong> port. Most commonly used GPS modules today integrate GPS, compass, safety switch, buzzer, and LED status light.</p><p>If you need to use assisted GPS, connect to the <strong>GPS2</strong> port.</p><p>The GPS/compass should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible (separating the compass from other electronics will reduce interference), with the direction markings towards the front of the vehicle (the arrow on the NEO GPS should match the arrow on the flight controller).</p><p><img src="'+a+'" alt="GPS"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The GPS module&#39;s integrated safety switch is enabled <em>by default</em> (when enabled, PX4 will not let you arm the vehicle). To disable the safety, press and hold the safety switch for 1 second. You can press the safety switch again to enable safety and disarm the vehicle (this can be useful if, for whatever reason, you are unable to disarm the vehicle from your remote control or ground station).</p></div><h2 id="radio-control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio-control" aria-label="Permalink to &quot;Radio Control&quot;">​</a></h2><p>A remote control (RC) radio system is required if you want to <em>manually</em> control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>You will need to <a href="./../getting_started/rc_transmitter_receiver">select a compatible transmitter/receiver</a> and then <em>bind</em> them so that they communicate (read the instructions that come with your specific transmitter/receiver).</p><p>Connection methods vary by remote controller and receiver type:</p><h3 id="android-remote-controllers" tabindex="-1">Android Remote Controllers <a class="header-anchor" href="#android-remote-controllers" aria-label="Permalink to &quot;Android Remote Controllers&quot;">​</a></h3><p>Take the H16 as an example:</p><p><img src="'+t+'" alt="H16 control"></p><p>Connect <strong>TELEM1/TELEM2</strong> to the UART0 port of the H16 remote controller, and link the H16’s SBUS pin to the <strong>RC IN</strong> port.</p><h3 id="sbus-dsm-ppm-protocol-receivers" tabindex="-1">SBUS/DSM/PPM Protocol Receivers <a class="header-anchor" href="#sbus-dsm-ppm-protocol-receivers" aria-label="Permalink to &quot;SBUS/DSM/PPM Protocol Receivers&quot;">​</a></h3><p><img src="'+n+'" alt="SBUS/DSM/PPM control"></p><p>Use wires to connect the receiver to the <strong>RC IN</strong> port at the rear of the controller.</p><h3 id="elrs-crsf-receivers" tabindex="-1">ELRS/CRSF Receivers <a class="header-anchor" href="#elrs-crsf-receivers" aria-label="Permalink to &quot;ELRS/CRSF Receivers&quot;">​</a></h3><p><img src="'+i+'" alt="ELRS/CRSF control"></p><p>Connect the <a href="./../telemetry/crsf_telemetry">ELRS/CRSF</a> receiver to any UART serial port of the X25 EVO (e.g., <strong>TELEM2</strong>).</p><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power&quot;">​</a></h2><p>The X25 EVO comes standard with the PMU2 Lite power module, which supports 20–70V input and can measure a maximum current of 220A. It can be directly connected to the <strong>Power C1/C2</strong> port of the X25 EVO and is plug-and-play (no configuration required).</p><p><img src="'+s+'" alt="Power"></p><h2 id="telemetry-radio-system" tabindex="-1">Telemetry (Radio) System <a class="header-anchor" href="#telemetry-radio-system" aria-label="Permalink to &quot;Telemetry (Radio) System&quot;">​</a></h2><p><a href="./../telemetry/">Telemetry system</a> allows you to communicate with the unmanned system via ground station software, enabling you to monitor and control the UAV’s status during flight. Connect the on-board unit of the telemetry system to the <strong>TELEM1</strong> or <strong>TELEM2</strong> port.</p><p>You can also purchase telemetry radios from the <a href="https://store.cuav.net/category/telemetry/" target="_blank" rel="noreferrer">CUAV store</a>.</p><p><img src="'+t+'" alt="Telemetry system"></p><h2 id="sd-card" tabindex="-1">SD Card <a class="header-anchor" href="#sd-card" aria-label="Permalink to &quot;SD Card&quot;">​</a></h2><p>SD cards are highly recommended as they are required for <a href="./../getting_started/flight_reporting">recording and analyzing flight details</a>, running tasks and using UAVCAN bus hardware. An SD card is already installed on X25 EVO when it leaves the factory.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For more information see <a href="./../getting_started/px4_basic_concepts#sd-cards-removable-memory">Basic Concepts &gt; SD Cards (Removable Memory)</a>.</p></div><h2 id="motors-servo" tabindex="-1">Motors/Servo <a class="header-anchor" href="#motors-servo" aria-label="Permalink to &quot;Motors/Servo&quot;">​</a></h2><p>Motors/servos are connected to the <strong>M1~M16</strong> ports in the order specified for your vehicle in the <a href="./../airframes/airframe_reference">Airframe Reference</a>.</p><p><img src="'+l+'" alt="Motors"></p><h2 id="servo-power-supply" tabindex="-1">Servo Power Supply <a class="header-anchor" href="#servo-power-supply" aria-label="Permalink to &quot;Servo Power Supply&quot;">​</a></h2><p>The X25 EVO does not supply power to servos. If you need to power servos:</p><ol><li>Connect a BEC to the positive and negative terminals of any column among <strong>M1 ~ M16</strong> (the positive and negative terminals of <strong>M1 ~ M16</strong> are interconnected).</li><li>Then connect the servos to the same column.</li></ol><p><img src="'+c+'" alt="servo power supply"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The power rail voltage must be appropriate for the servo being used!</p></div><h2 id="other-peripherals" tabindex="-1">Other Peripherals <a class="header-anchor" href="#other-peripherals" aria-label="Permalink to &quot;Other Peripherals&quot;">​</a></h2><p>The wiring and configuration of optional/less common components is covered within the topics for individual <a href="./../peripherals/">peripherals</a>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>General configuration information is covered in: <a href="./../config/">Autopilot Configuration</a>.</p><p>QuadPlane-specific configuration is covered here: <a href="./../config_vtol/vtol_quad_configuration">QuadPlane VTOL Configuration</a></p><h2 id="further-information" tabindex="-1">Further information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further information&quot;">​</a></h2><ul><li><a href="https://doc.cuav.net/" target="_blank" rel="noreferrer">CUAV Docs</a> (CUAV)</li><li><a href="./../flight_controller/cuav_x25-evo">X25 EVO</a> (PX4 Doc Overview page)</li><li><a href="./../flight_controller/cuav_x25-super">X25 SUPER</a> (PX4 Doc Overview page)</li><li>[<a href="./../flight_controller/cuav_x25-mega">X25 MEGA</a>] (PX4 Doc Overview page)</li></ul>',57)])])}const x=d(m,[["render",f]]);export{P as __pageData,x as default};
